<template><div class="app-container"><h1>骑手管理</h1><p>骑手只能查看待接配送单和自己的配送记录。存在配送中订单时不能停用账号。</p><el-button type="primary" @click="visible=true">新增骑手账号</el-button><el-table :data="rows" v-loading="loading"><el-table-column prop="name" label="姓名"/><el-table-column prop="user_name" label="登录账号"/><el-table-column prop="phone" label="电话"/><el-table-column label="配送中 / 上限"><template #default="{row}">{{row.active_orders}} / {{row.max_active}}</template></el-table-column><el-table-column label="状态"><template #default="{row}">{{row.active?'启用':'停用'}}</template></el-table-column><el-table-column label="操作"><template #default="{row}"><el-button link :disabled="busy" @click="setLimit(row)">配送上限</el-button><el-button link :disabled="busy" @click="toggle(row)">{{row.active?'停用':'启用'}}</el-button></template></el-table-column></el-table><el-dialog v-model="visible" title="创建骑手" width="440px"><el-form label-width="90px"><el-form-item label="账号"><el-input v-model="form.username" placeholder="4至20位字母、数字或下划线"/></el-form-item><el-form-item label="初始密码"><el-input v-model="form.password" type="password" show-password placeholder="10至20位"/></el-form-item><el-form-item label="姓名"><el-input v-model="form.name" maxlength="60"/></el-form-item><el-form-item label="手机号"><el-input v-model="form.phone" maxlength="11"/></el-form-item></el-form><template #footer><el-button @click="visible=false">取消</el-button><el-button type="primary" :loading="busy" @click="create">创建</el-button></template></el-dialog></div></template>
<script setup>
import {ref,onMounted} from 'vue';import request from '@/utils/request';import {ElMessageBox,ElMessage} from 'element-plus';const rows=ref([]),loading=ref(false),busy=ref(false),visible=ref(false),form=ref({});async function load(){loading.value=true;try{rows.value=(await request({url:'/food/delivery/riders'})).data}finally{loading.value=false}}async function create(){busy.value=true;try{await request({url:'/food/delivery/riders',method:'post',data:form.value});form.value={};visible.value=false;ElMessage.success('骑手账号已创建');await load()}finally{busy.value=false}}async function toggle(row){try{await ElMessageBox.confirm('确认'+(row.active?'停用':'启用')+'骑手 '+row.name+'？')}catch{return}busy.value=true;try{await request({url:'/food/delivery/riders/'+row.user_id+'/active',method:'post',data:{active:row.active?0:1}});await load()}finally{busy.value=false}}async function setLimit(row){let value;try{({value}=await ElMessageBox.prompt('设置同时配送的最大单数（1至50）。','配送上限',{inputValue:String(row.max_active),inputValidator:v=>/^\d+$/.test(v)&&Number(v)>=1&&Number(v)<=50||'请输入1至50的整数'}))}catch{return}busy.value=true;try{await request({url:'/food/delivery/riders/'+row.user_id+'/limit',method:'post',data:{maxActive:Number(value)}});await load()}finally{busy.value=false}}onMounted(load);
</script>
